import { useState, useEffect } from 'react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export default function UserDashboard() {
  const [userData, setUserData] = useState(null);
  const [cardData, setCardData] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const userInfo = JSON.parse(localStorage.getItem('userInfo'));
    if (!userInfo) {
      navigate('/user/login');
      return;
    }

    const fetchData = async () => {
      try {
        const config = { headers: { Authorization: `Bearer ${userInfo.token}` } };
        
        // Fetch user profile
        const userRes = await axios.get(`http://localhost:5000/api/users/${userInfo._id}`, config);
        setUserData(userRes.data);

        // Fetch linked card (matching assignedTo)
        const cardRes = await axios.get(`http://localhost:5000/api/cards/user/${userInfo._id}`);
        setCardData(cardRes.data); // Contains pointBalance

        // Fetch transaction history
        const txRes = await axios.get(`http://localhost:5000/api/transactions/user/${userInfo._id}`);
        setTransactions(txRes.data);
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [navigate]);

  if (loading) return <div className="text-center py-20 text-gray-500">Loading dashboard...</div>;

  return (
    <div className="w-full max-w-4xl mx-auto p-6 space-y-6">
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-6 text-white shadow-lg flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm font-medium">Welcome back, {userData?.fullName}</p>
          <h1 className="text-3xl font-bold mt-1">
            {cardData?.pointBalance || 0} <span className="text-lg font-normal">Points</span>
          </h1>
          <p className="text-xs text-blue-200 mt-1">Card UID: {cardData?.rfidUid || 'No Card Linked Yet'}</p>
        </div>
        <button 
          onClick={() => { localStorage.removeItem('userInfo'); navigate('/user/login'); }}
          className="bg-white/10 px-4 py-2 rounded-xl backdrop-blur-md text-sm border border-white/20 hover:bg-white/20 transition-colors"
        >
          Logout
        </button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-100">
          <h2 className="text-lg font-bold text-gray-800">Transaction History</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 text-xs font-semibold uppercase tracking-wider text-gray-500">
                <th className="px-6 py-3">Type</th>
                <th className="px-6 py-3">Points</th>
                <th className="px-6 py-3">Balance After</th>
                <th className="px-6 py-3">Naira Value</th>
                <th className="px-6 py-3">Date</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 text-sm text-gray-700">
              {transactions.length === 0 ? (
                <tr>
                  <td colSpan="5" className="px-6 py-6 text-center text-gray-400">No transactions recorded yet.</td>
                </tr>
              ) : (
                transactions.map((tx) => (
                  <tr key={tx._id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 font-medium capitalize">
                      <span className={`px-2 py-1 rounded-full text-xs font-semibold ${tx.type === 'topup' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                        {tx.type}
                      </span>
                    </td>
                    <td className={`px-6 py-4 font-semibold ${tx.type === 'topup' ? 'text-green-600' : 'text-red-600'}`}>
                      {tx.type === 'topup' ? `+${tx.pointsInvolved}` : `-${tx.pointsInvolved}`}
                    </td>
                    <td className="px-6 py-4">{tx.balanceAfter} pts</td>
                    <td className="px-6 py-4 text-gray-500">₦{tx.fiatValueNaira}</td>
                    <td className="px-6 py-4 text-gray-400 text-xs">{new Date(tx.timestamp).toLocaleString()}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
